rebuild();overview();resize();$('#loading').hidden=true;const clock=new THREE.Clock();renderer.setAnimationLoop(()=>{const dt=Math.min(clock.getDelta(),.05);if(mode==='walk'){camera.rotation.set(pitch,yaw,0,'YXZ');let f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),r=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);const n=Math.hypot(f,r);if(n){f/=n;r/=n;const dist=config.settings.speed*dt,dx=(-Math.sin(yaw)*f+Math.cos(yaw)*r)*dist,dz=(-Math.cos(yaw)*f-Math.sin(yaw)*r)*dist;const steps=Math.ceil(dist/40);for(let i=0;i<steps;i++){let x=camera.position.x*1000,z=camera.position.z*1000;if(!playerBlocked(config,parts,furniture.items,x+dx/steps,z))camera.position.x+=mm(dx/steps);x=camera.position.x*1000;if(!playerBlocked(config,parts,furniture.items,x,z+dz/steps))camera.position.z+=mm(dz/steps);}}}else orbit.update();renderer.render(scene,camera);});
